-- Frozen additive revision: bytes stay in private uploads; metadata stays relational.
CREATE TABLE IF NOT EXISTS languages (code VARCHAR(35) PRIMARY KEY NOT NULL, name VARCHAR(100) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT 1, direction VARCHAR(3) NOT NULL DEFAULT 'ltr' CHECK(direction IN ('rtl','ltr')));
CREATE TABLE IF NOT EXISTS audit_events (id INTEGER PRIMARY KEY, actor_user_id INTEGER REFERENCES users(id) ON DELETE RESTRICT, action VARCHAR(100) NOT NULL, entity_type VARCHAR(60) NOT NULL, entity_id VARCHAR(80) NOT NULL, changes JSON NOT NULL, source VARCHAR(20) NOT NULL, request_id VARCHAR(36) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS directorate_translations (directorate_id INTEGER NOT NULL REFERENCES directorates(id) ON DELETE CASCADE, language_code VARCHAR(35) NOT NULL REFERENCES languages(code) ON DELETE RESTRICT, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, location VARCHAR(500) NOT NULL, PRIMARY KEY(directorate_id,language_code));
CREATE TABLE IF NOT EXISTS files (id INTEGER PRIMARY KEY, storage_disk VARCHAR(30) NOT NULL DEFAULT 'local', storage_key VARCHAR(500) NOT NULL UNIQUE, original_name VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, size_bytes INTEGER, checksum VARCHAR(64), uploaded_by_user_id INTEGER REFERENCES users(id) ON DELETE RESTRICT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS permission_translations (permission_code VARCHAR(80) NOT NULL REFERENCES permissions(code) ON DELETE CASCADE, language_code VARCHAR(35) NOT NULL REFERENCES languages(code) ON DELETE RESTRICT, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, PRIMARY KEY(permission_code,language_code));
CREATE TABLE IF NOT EXISTS role_translations (role_id INTEGER NOT NULL REFERENCES roles(id) ON DELETE CASCADE, language_code VARCHAR(35) NOT NULL REFERENCES languages(code) ON DELETE RESTRICT, name VARCHAR(150) NOT NULL, description TEXT NOT NULL, PRIMARY KEY(role_id,language_code));
CREATE TABLE IF NOT EXISTS user_languages (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, language_code VARCHAR(35) NOT NULL REFERENCES languages(code) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS citizen_files (file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE RESTRICT, citizen_id INTEGER NOT NULL REFERENCES citizens(id) ON DELETE RESTRICT, purpose VARCHAR(30) NOT NULL, is_current BOOLEAN NOT NULL, PRIMARY KEY(file_id,citizen_id));
CREATE TABLE IF NOT EXISTS complaint_files (file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE RESTRICT, complaint_id INTEGER NOT NULL REFERENCES complaints(id) ON DELETE RESTRICT, legacy_attachment_id INTEGER UNIQUE REFERENCES attachments(id) ON DELETE RESTRICT, PRIMARY KEY(file_id,complaint_id));
CREATE TABLE IF NOT EXISTS complaint_history (id INTEGER PRIMARY KEY, complaint_id INTEGER NOT NULL REFERENCES complaints(id) ON DELETE RESTRICT, actor_user_id INTEGER REFERENCES users(id) ON DELETE RESTRICT, event VARCHAR(30) NOT NULL, old_status VARCHAR(30), new_status VARCHAR(30) NOT NULL, old_directorate_id INTEGER REFERENCES directorates(id) ON DELETE RESTRICT, new_directorate_id INTEGER NOT NULL REFERENCES directorates(id) ON DELETE RESTRICT, old_progress INTEGER, new_progress INTEGER NOT NULL, reason VARCHAR(1000) NOT NULL, source VARCHAR(20) NOT NULL, request_id VARCHAR(36) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS evidence_reply_files (file_id INTEGER NOT NULL REFERENCES files(id) ON DELETE RESTRICT, reply_id INTEGER NOT NULL REFERENCES evidence_replies(id) ON DELETE RESTRICT, legacy_evidence_file_id INTEGER UNIQUE REFERENCES evidence_files(id) ON DELETE RESTRICT, PRIMARY KEY(file_id,reply_id));
CREATE INDEX IF NOT EXISTS ix_audit_events_action ON audit_events(action);
CREATE INDEX IF NOT EXISTS ix_audit_events_actor_user_id ON audit_events(actor_user_id);
CREATE INDEX IF NOT EXISTS ix_audit_events_created_at ON audit_events(created_at);
CREATE INDEX IF NOT EXISTS ix_audit_events_entity_type ON audit_events(entity_type);
CREATE INDEX IF NOT EXISTS ix_complaint_files_complaint_id ON complaint_files(complaint_id);
CREATE INDEX IF NOT EXISTS ix_complaint_history_complaint_id ON complaint_history(complaint_id);
CREATE INDEX IF NOT EXISTS ix_evidence_reply_files_reply_id ON evidence_reply_files(reply_id);
